def execute_rebuild(item):
    response = rebuild_index(item)
    response = {'ok': True}
    logger.warning(json.dump(response))
    return response


def run_in_threads(lista):
    resultados = []
    with ThreadPoolExecutor(max_workers=10) as executor:
        # Submete as tarefas ao pool de threads
        futures = {executor.submit(execute_rebuild, item): item for item in lista}

        # Usa tqdm para exibir a barra de progresso
        for future in tqdm(as_completed(futures), total=len(lista), desc="Rebuilding Index", unit="item"):
            resultados.append(future.result())
            logger.info(future.result())
    logger.info(resultados)
    return resultados


