def get_token():
    client = RestTemplate(base_url=properties["token"]["host"], headers=no_auth_headers)
    uri=properties["token"]["uri"]
    credentials = properties["token"]["credentials"]

    resposta = client.post(uri, json=credentials, headers=no_auth_headers)
    return resposta['access_token']


